446	function checkForUpdates() {
447	  const currentVersion = pkg.version ?? '0.0.0';
448	  try {
449	    const remote = execSync('npm view frai version', { encoding: 'utf8' }).trim();
450	    if (!remote) {
451	      log.warn('Unable to determine latest version from npm.');
452	      return;
453	    }
454	    if (remote === currentVersion) {
455	      log.success('You are running the latest FRAI CLI release.', { version: currentVersion });
456	    } else {
457	      log.info('A newer FRAI CLI release is available.', {
458	        current: currentVersion,
459	        latest: remote
460	      });
461	      console.log(`Update with: npm install -g frai@${remote}`);
462	    }
463	  } catch (error) {
464	    log.warn('Failed to check for updates.', {
465	      error: error instanceof Error ? error.message : String(error)
466	    });
467	  }
468	}
