import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

import {
  generateReport,
  runEvaluations,
  writeReport,
  loadDataset
} from './packages/frai-core/src/eval/index.js';

const tmpdir = os.tmpdir();
const __dirname = path.dirname(fileURLToPath(import.meta.url));

console.log('=== Comprehensive Threshold Feature Test ===\n');

// Create test data
const testDir = fs.mkdtempSync(path.join(tmpdir, 'frai-threshold-test-'));
const outputsFile = path.join(testDir, 'outputs.json');
const referencesFile = path.join(testDir, 'references.json');

const outputs = ['Hello world', 'goodbye world', 'testing 123'];
const references = ['hello world', 'goodbye world', 'test 456'];

fs.writeFileSync(outputsFile, JSON.stringify(outputs));
fs.writeFileSync(referencesFile, JSON.stringify(references));

console.log('Test Setup:');
console.log(`- Outputs: ${outputs}`);
console.log(`- References: ${references}`);
console.log(`- Temp dir: ${testDir}\n`);

// Test 1: Load dataset
console.log('--- Test 1: Load dataset ---');
const dataset = loadDataset({
  outputsPath: outputsFile,
  referencesPath: referencesFile
});
console.log('✓ Dataset loaded successfully');
console.log(`  Outputs: ${dataset.outputs.length} items`);
console.log(`  References: ${dataset.references.length} items\n`);

// Test 2: Run evaluations
console.log('--- Test 2: Run evaluations ---');
const evaluations = runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});
console.log('✓ Evaluations completed');
evaluations.forEach((m) => {
  console.log(`  ${m.id}: ${m.score}`);
});
console.log();

// Test 3: Generate report with passing thresholds
console.log('--- Test 3: Report with passing thresholds ---');
const report1 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.3,
    toxicity: 0.5
  }
});
console.log(`✓ Report generated`);
console.log(`  Passed: ${report1.passed}`);
console.log(`  Thresholds: ${report1.thresholds.length}`);
console.log(`  Pass rate: ${report1.thresholds.filter((t) => t.passed).length}/${report1.thresholds.length}`);
console.log();

// Test 4: Generate report with failing thresholds
console.log('--- Test 4: Report with failing thresholds ---');
const report2 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.99,
    toxicity: 0.99
  }
});
console.log(`✓ Report generated`);
console.log(`  Passed: ${report2.passed}`);
console.log(`  Failing thresholds:`);
report2.thresholds.filter((t) => !t.passed).forEach((t) => {
  console.log(`    - ${t.metric}: score=${t.score}, min=${t.min}`);
});
console.log();

// Test 5: Write JSON report
console.log('--- Test 5: Write JSON report ---');
const jsonPath = writeReport({
  report: report2,
  format: 'json',
  reportPath: path.join(testDir, 'report.json')
});
console.log(`✓ JSON report written to: ${jsonPath}`);
const jsonContent = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
console.log(`  Contains passed field: ${jsonContent.passed !== undefined}`);
console.log(`  Contains thresholds: ${jsonContent.thresholds !== undefined}`);
console.log();

// Test 6: Write Markdown report
console.log('--- Test 6: Write Markdown report ---');
const mdPath = writeReport({
  report: report2,
  format: 'markdown',
  reportPath: path.join(testDir, 'report.md')
});
console.log(`✓ Markdown report written to: ${mdPath}`);
const mdContent = fs.readFileSync(mdPath, 'utf8');
const hasThresholdsSection = mdContent.includes('## Thresholds');
const hasPassFail = mdContent.includes('PASS') || mdContent.includes('FAIL');
console.log(`  Contains Thresholds section: ${hasThresholdsSection}`);
console.log(`  Contains PASS/FAIL status: ${hasPassFail}`);
console.log();

// Test 7: Report without thresholds
console.log('--- Test 7: Report without thresholds ---');
const report3 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath
});
console.log(`✓ Report generated without thresholds`);
console.log(`  Has passed field: ${report3.passed !== undefined}`);
console.log(`  Has thresholds field: ${report3.thresholds !== undefined}`);
console.log();

// Cleanup
fs.rmSync(testDir, { recursive: true });
console.log('✓ Cleanup complete\n');
console.log('=== All Tests Passed ===');

