export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdResults = null;
  let passed = true;

  if (thresholds && typeof thresholds === 'object') {
    thresholdResults = [];
    const metricMap = new Map(evaluations.map((m) => [m.id, m]));

    for (const [metricId, minScore] of Object.entries(thresholds)) {
      const metric = metricMap.get(metricId);
      if (!metric) {
        throw new Error(`Unknown metric: ${metricId}`);
      }

      const score = metric.score ?? null;
      const thresholdPassed = score !== null && score >= minScore;
      if (!thresholdPassed) {
        passed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min: minScore,
        score,
        passed: thresholdPassed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults !== null) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

